<?php
use watrlabs\authentication;

global $db;
$auth = new authentication();
$auth->requiresession();
$admin = $auth->getuserinfo();
if (!$admin || (int)$admin->is_admin !== 1) { http_response_code(403); die('ur not an admin bud'); }

$message = isset($_GET['message']) ? htmlspecialchars($_GET['message'], ENT_QUOTES, 'UTF-8') : '';
$error = isset($_GET['error']) ? htmlspecialchars($_GET['error'], ENT_QUOTES, 'UTF-8') : '';
$q = trim($_GET['q'] ?? '');
$assetQ = trim($_GET['asset_q'] ?? '');

$usersQuery = $db->table('users')->orderBy('id', 'DESC');
if ($q !== '') {
    $like = '%' . $q . '%';
    $usersQuery = $usersQuery->where(function($query) use ($like) {
        $query->where('username', 'LIKE', $like)->orWhere('id', 'LIKE', $like);
    });
}
$users = $usersQuery->limit(100)->get();
$allUsers = $db->table('users')->orderBy('username', 'ASC')->get();
$assetQuery = $db->table('assets')->orderBy('id', 'DESC');
if ($assetQ !== '') $assetQuery = $assetQuery->where('name', 'LIKE', '%' . $assetQ . '%');
$assets = $assetQuery->limit(100)->get();

$userCount = $db->table('users')->count();
$assetCount = $db->table('assets')->count();
$messageCount = $db->table('messages')->count();
$ownedCount = $db->table('ownedassets')->count();
$admins = $db->table('users')->where('is_admin', 1)->count();
$universeCount = $db->table('universes')->count();
$groupCount = $db->table('groups')->count();
$moderationCount = $db->table('moderation')->count();
$jobCount = $db->table('jobs')->count();
$recentModeration = $db->table('moderation')->orderBy('id', 'DESC')->limit(30)->get();
$recentMessages = $db->table('messages')->orderBy('id', 'DESC')->limit(30)->get();
$recentUsers = $db->table('users')->orderBy('id', 'DESC')->limit(12)->get();
$recentAssets = $db->table('assets')->orderBy('id', 'DESC')->limit(12)->get();

$appName = $_ENV["APP_NAME"];
?>
