<section id="system" class="section"><div class="grid2"><div class="box"><h2>Runtime</h2><div class="boxbody"><p><b>PHP:</b> <?=htmlspecialchars(PHP_VERSION)?></p><p><b>Server:</b> <?=htmlspecialchars($_SERVER['SERVER_SOFTWARE'] ?? 'PHP built-in server')?></p><p><b>OS:</b> <?=htmlspecialchars(PHP_OS)?></p><p><b>Time:</b> <?=date('Y-m-d H:i:s')?></p><p><b>Database:</b> <?=htmlspecialchars($_ENV['DB_NAME'] ?? 'configured')?></p></div></div><div class="box"><h2>Maintenance</h2><div class="boxbody"><p>Current MAINTENANCE: <b><?=htmlspecialchars($_ENV['MAINTENANCE'] ?? 'unknown')?></b></p><p>Current ACTUAL_MAINTENANCE: <b><?=htmlspecialchars($_ENV['ACTUAL_MAINTENANCE'] ?? 'unknown')?></b></p><p class="muted">Edit .env manually if you need to change maintenance mode.</p></div></div></div></section>

<section id="help" class="section"><div class="box"><h2>Administrator Help</h2><div class="boxbody"><p>This panel uses the authentication and database. The blue navigation buttons switch between management categories without leaving the page.</p><p><b>Economy:</b> grant ROBUX/Tix and membership. <b>Catalog:</b> create, feature, mark limited, grant and delete assets. <b>Moderation:</b> warnings and bans. <b>System:</b> runtime information.</p><p class="muted">Always keep a database backup before bulk destructive operations.</p></div></div></section>
</main></div><div class="footer"><?=htmlspecialchars($appName)?> Administration &bull; Classic Roblox-inspired interface</div></div>
<script>
const titles={dashboard:'Administration',users:'User Management',economy:'Economy & Membership',catalog:'Catalog Management',moderation:'Moderation',messages:'Private Messages',games:'Games & Groups',control:'Control Center',system:'System Information',help:'Help'};
function showTab(id){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));const s=document.getElementById(id),b=document.querySelector('.tab[data-tab="'+id+'"]');if(s)s.classList.add('active');if(b)b.classList.add('active');const t=document.getElementById('pageTitle');if(t)t.textContent=titles[id]||'Administration';history.replaceState(null,'','#'+id);}
function focusAdmin(tab, selector){showTab(tab);setTimeout(function(){const el=document.querySelector('#'+tab+' '+selector);if(el){el.focus();el.scrollIntoView({behavior:'smooth',block:'center'});}},40);}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));
if(location.hash)showTab(location.hash.slice(1));
// Classic admin keyboard shortcuts.
//document.addEventListener('keydown',function(e){if(e.ctrlKey||e.metaKey)return;const k=e.key.toLowerCase();if(k==='u')focusAdmin('users','input[name=q]');else if(k==='e')focusAdmin('economy','input[name=robux]');else if(k==='c')focusAdmin('catalog','input[name=asset_q]');else if(k==='m')focusAdmin('moderation','textarea[name=note]');else if(k==='p')focusAdmin('messages','input[name=subject]');else if(k==='r')location.reload();});
</script></body></html>
